import ballerina/io;

public function main() {
    int[] xs = [1, 2, 3, 4];
    int[][] r = from var x in xs
        let int m = x % 2
        group by m
        let function () returns int[] f = function () returns int[] { return [x]; }
        select f();
    io:println(r);
    int v = r[0][0];
    io:println(v + 1);
}

